16	    info(message, meta) {
17	        console.log(formatLog('info', message, meta));
18	    },
19	    success(message, meta) {
20	        console.log(formatLog('success', message, meta));
21	    },
22	    warn(message, meta) {
23	        console.warn(formatLog('warn', message, meta));
24	    },
25	    error(message, meta) {
26	        console.error(formatLog('error', message, meta));
27	    }
28	};
29	function formatLog(level, message, meta = undefined) {
30	    const timestamp = new Date().toISOString();
31	    if (!meta || Object.keys(meta).length === 0) {
32	        return `[${timestamp}] ${level.toUpperCase()} ${message}`;
33	    }
34	    let serializedMeta = '';
35	    try {
36	        serializedMeta = JSON.stringify(meta);
37	    }
38	    catch (error) {
39	        serializedMeta = String(meta);
40	    }
41	    return `[${timestamp}] ${level.toUpperCase()} ${message} ${serializedMeta}`;
42	}
