        log.warn('Failed to check for updates.', {
            error: error instanceof Error ? error.message : String(error)
        });
    }
}
function assertFileExists(targetPath) {
    if (!fs.existsSync(targetPath)) {
        throw new Error(`File not found: ${targetPath}`);
    }
}
function parseThresholds(thresholdStrs) {
    if (!thresholdStrs || thresholdStrs.length === 0) {
        return { thresholds: null, isValid: true };
    }
    const thresholds = {};
    for (const str of thresholdStrs) {
        const match = str.match(/^([a-z_]+)=(.+)$/);
        if (!match) {
            return { thresholds: null, isValid: false, error: `Malformed threshold: ${str}. Expected format: <metric>=<number>` };
        }
        const [, metricId, valueStr] = match;
        const value = parseFloat(valueStr);
        if (Number.isNaN(value) || value < 0 || value > 1) {
            return { thresholds: null, isValid: false, error: `Invalid threshold value for ${metricId}: ${valueStr}. Must be a number between 0 and 1.` };
        }
        thresholds[metricId] = value;
    }
    return { thresholds, isValid: true };
}
function runEvalCommand(options) {
    assertFileExists(options.outputs);
    const { thresholds, isValid, error } = parseThresholds(options.threshold);
    if (!isValid) {
        log.error(error ?? 'Invalid threshold');
        process.exit(2);
    }
    const dataset = Eval.loadDataset({
        outputsPath: options.outputs,
        referencesPath: options.references
    });
    const evaluations = Eval.runEvaluations({
        outputs: dataset.outputs,
        references: dataset.references
    });
    let report;
    try {
        report = Eval.generateReport({
            evaluations,
            outputsPath: dataset.outputsPath,
            referencesPath: dataset.referencesPath,
            thresholds
        });
    }
    catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        if (message.startsWith('Unknown metric:')) {
            log.error(message);
            process.exit(2);
        }
        throw error;
    }
    const resolvedPath = Eval.writeReport({
        report,
        format: options.format ?? 'json',
        reportPath: options.report
    });
